/** Combat-tick action handlers — split from state_actions.ts per ADR-0110.
 *
 * - applyCombatAction: combat phase dispatch (cycle target, use program, jack out)
 * - cycleTarget / advanceDeadTarget: active-ICE targeting
 * - drawHand: recycle discard into a fresh hand when the deck empties
 * - processEnemyTurns: enemy auto-attack / skill tick
 *
 * Program resolution lives in `state_actions_programs.ts`; non-combat phase
 * handlers live in `state_actions_phases.ts`. All three are re-exported from
 * `state_actions.ts` so existing imports keep working.
 */

import type { GameState, GameAction, Ice, BossPhase } from "../types";
import type { CombatVfxInstance } from "../../renderer/combat_vfx";
import { AUTO_ATTACK_INTERVAL_MS, COMBO_BONUSES } from "./combat_engine";
import { DEFAULT_BOSS_PROFILE, checkPhaseTransition } from "./boss_phases";
import { enemyShouldUseSkill, selectSkillByPersonality } from "./ice_ai";
import { rollIceCrit } from "./ice_crit";
import { alarmDamage } from "./idle_alarm";
import { iceAttackBonus, tickIceEffects } from "./ice_combat_effects";
import { applyPlayerMitigation } from "./player_mitigation";
import { playerEvasionPct } from "./player_mitigation";
import { NANO_REGEN_HP, REVIVE_HP_PCT, loadoutHasEffect } from "../state/extra_effects";
import {
  applyCase,
  caseNote,
  incomingOddsFor,
  resolveAttackCase,
  type AttackCase,
} from "./attack_resolution";
import { applyIceNonDamageEffect } from "./ice_combat_effect_apply";
import { endedStatuses, statusEventLines } from "../status";
import { iceDmgBonusPctForGrade, missionGradeOf } from "./ice_scaling";
import { isMutatorActive, type MutableRunState } from "../state/run_mutators";
import { createDeceasedJockey, generateDeathSummary } from "../state/death_cycle";
import {
  COMBAT_LOG_CAP,
  import_vfx_deterministic,
  import_vfx_ms,
  durationForKind,
  durationMsForKind,
} from "../state/state_helpers";
import { useProgram, advanceDeadTarget } from "./state_actions_programs";
import { everyProgramBlocked } from "./program_affordance";
import { refillHand } from "./hand";
import { creditKills, killedBetween, resolveVictory } from "./victory";

/** Dixie companion tuning (ADR-0244 option 2).
 * N=2 preserves the 2000ms harness baseline: first player turn, then alternate
 * successful program plays. Initial counter N-1 preserves that opening phase.
 * Changing N is a separate balance decision; damage remains 8 + combo * 3.
 * Exported for the design-conformance suite; see docs/design/systems/combat.md.
 */
export const DIXIE_ATTACK_EVERY_N_PLAYER_TURNS = 2;
export const DIXIE_BASE_DAMAGE = 8;
export const DIXIE_SYNERGY_BONUS = 3;

/** The combo ceiling the damage table defines: `COMBO_BONUSES` ends at 6 and
 * a card above it already falls back to 1.0. Dixie's synergy read the raw
 * counter, which nothing resets inside a run (`openArrivalEncounter` keeps
 * it), so by the later fights she hit for 68-92 while a card hit for 4-17 --
 * the ally fought the fights and the player watched (ADR-0268). */
export const MAX_COMBO = Math.max(...Object.keys(COMBO_BONUSES).map(Number));

/** Dixie's damage for a combo, capped at the ceiling the combo system defines. */
export function dixieDamage(combo: number): number {
  return DIXIE_BASE_DAMAGE + Math.min(combo, MAX_COMBO) * DIXIE_SYNERGY_BONUS;
}

export function applyCombatAction(state: GameState, action: GameAction): GameState {
  if (action.type === "cycle_target") {
    return cycleTarget(state);
  }
  if (action.type === "select_program") {
    const idx = action.handIndex - 1;
    if (idx < 0 || idx >= state.deck.length) {
      return {
        ...state,
        message:
          state.deck.length === 0
            ? "Hand empty — no programs to play"
            : `Hand slot ${action.handIndex} is empty`,
      };
    }
    return state;
  }
  if (action.type === "use_program") {
    const result = useProgram(state, action.programId);
    if (result.deck.length === state.deck.length) return result;
    return finishPlayerTurn(result);
  }
  // ADR-0266: when every program in hand is over the COST limit, playing is
  // refused and the hand never empties -- so the turn never advanced and the
  // fight froze until JACK OUT. ENTER now ends that turn instead: the hand is
  // discarded, the enemies act, and a fresh hand is dealt. COST does not
  // fall, so the pressure stands and the run is decided by the fight, not by
  // a screen that stopped answering.
  if (action.type === "confirm" && everyProgramBlocked(state)) {
    const discarding: GameState = {
      ...state,
      deck: [],
      discardPile: [...state.discardPile, ...state.deck],
    };
    const passed = finishPlayerTurn(discarding);
    return passed.runPhase === "combat"
      ? { ...passed, message: "COST capped — turn passed" }
      : passed;
  }
  if (action.type === "jack_out") {
    return {
      ...state,
      runPhase: "dead",
      phase: "defeat",
      message: "Jacked out — mission failed",
    };
  }
  return state;
}

/** The tail of a player action: the enemies act, the empty hand recycles, and a
 * wiped roster resolves as a victory. Shared by playing a program and by passing
 * a turn (ADR-0266), so both can reach the same outcome.
 *
 * ADR-0280: **one enemy phase per player action**, off the turn rather than off
 * a wall clock. That is the model the balance harness has always simulated
 * (`scripts/balance_sim.ts` advanced the clock once per action), so the recorded
 * grade curve finally describes play instead of a clock nobody could predict.
 * A wall-clock gate also made difficulty depend on how long the player spent on
 * a card, and put a clock read inside the reducer.
 *
 * The hand still recycles only when it empties (ADR-0212): `drawHand` stays
 * gated on that, while the enemy phase runs every action.
 */
function finishPlayerTurn(state: GameState): GameState {
  const handEmptied = state.deck.length === 0;
  const afterEnemies = processEnemyTurns(state);
  const afterDixie = processDixieTurn(afterEnemies);
  const ready = handEmptied ? drawHand(afterDixie) : afterDixie;
  // ADR-0278: a kill that lands in the enemy phase (Dixie, a DoT) owes the
  // player the same loot and the same achievements as a program kill. The
  // loot belongs to the kill, so it is credited where the kill happened.
  const { state: withLoot, drops } = creditKills(ready, state.iceRoster, ready.iceRoster);
  const allDefeated = withLoot.iceRoster.every((ice) => ice.hp === 0);
  if (allDefeated && withLoot.iceRoster.length > 0 && withLoot.runPhase === "combat") {
    return resolveVictory(withLoot, {
      defeated: killedBetween(state.iceRoster, withLoot.iceRoster),
      drops,
      kind: "companion",
    });
  }
  return withLoot;
}

function cycleTarget(state: GameState): GameState {
  const aliveIndices: number[] = [];
  for (let i = 0; i < state.iceRoster.length; i++) {
    if (state.iceRoster[i].hp > 0) aliveIndices.push(i);
  }
  if (aliveIndices.length === 0) return state;
  const currentPos = aliveIndices.indexOf(state.activeIceIndex);
  const nextPos = (currentPos + 1) % aliveIndices.length;
  return { ...state, activeIceIndex: aliveIndices[nextPos] };
}

/** Card draw (ADR-0212 step-4): when the hand empties, recycle the discard into
 * the draw pile and deal a fresh hand so combat can continue past the opening 5
 * cards. Order is preserved (no shuffle) so the draw consumes no RNG and stays
 * deterministic; the fight is bounded by the alarm cap. Runs after the enemy
 * turn so the "was a program played" guard in applyCombatAction still works.
 *
 * ADR-0278: the same refill is used when the loot screen closes, so a fight
 * opens on a full hand and a card taken at the loot screen is dealt.
 */
function drawHand(state: GameState): GameState {
  if (state.deck.length > 0) return state;
  return refillHand(state);
}

function processDixieTurn(state: GameState): GameState {
  const turns = state.dixiePlayerTurnsSinceAttack + 1;
  const targetIdx = state.iceRoster.findIndex((ice) => ice.hp > 0);
  if (turns < DIXIE_ATTACK_EVERY_N_PLAYER_TURNS || targetIdx < 0) {
    return { ...state, dixiePlayerTurnsSinceAttack: turns };
  }
  const dixieDmg = dixieDamage(state.playerCombo);
  const message = `>>> Dixie attacks: ${dixieDmg} dmg`;
  return {
    ...state,
    dixiePlayerTurnsSinceAttack: 0,
    iceRoster: state.iceRoster.map((ice, i) =>
      i === targetIdx ? { ...ice, hp: Math.max(0, ice.hp - dixieDmg) } : ice,
    ),
    message: state.phase === "defeat" ? state.message : message,
    combatLog:
      state.phase === "defeat"
        ? state.combatLog
        : [message, ...state.combatLog].slice(0, COMBAT_LOG_CAP),
  };
}

/** One incoming attack, resolved through the SRW cases (ADR-0321).
 *
 * The order is fixed and deliberate:
 *
 *   1. the CASE (miss / guard / hit) — one draw, always
 *   2. the crit roll — the ICE's own band, on top of the case
 *   3. the shield pool (ADR-0255)
 *
 * The case comes FIRST so a dodged attack never spends the barrier (the runner
 * did not need it) and so the draw order does not depend on which archetype is
 * attacking — a positional mock in a test can pin the ICE's rolls.
 */
/** What one resolved incoming attack did, before it reaches the player's HP. */
interface ResolvedHit {
  readonly state: GameState;
  readonly damage: number;
  readonly absorbed: number;
  readonly attackCase: AttackCase;
  readonly isCrit: boolean;
}

function resolveIncomingHit(
  state: GameState,
  enemy: Ice,
  rawDamage: number,
  rng: () => number,
): ResolvedHit {
  const odds = incomingOddsFor(playerEvasionPct(state));
  // ADR-0321: with nothing to roll there is no draw, so the seeded stream — and
  // therefore every recorded balance curve — is unchanged until a card or the
  // owner's table gives the cases something to do.
  const attackCase: AttackCase =
    odds.missPct <= 0 && odds.guardPct <= 0 ? "hit" : resolveAttackCase(rng(), odds);
  // ADR-0161 `aggressive` archetype: +5% crit chance. Rolled after the case so
  // the sequence is the same whatever the archetype.
  const crit = rollIceCrit(enemy, rawDamage, rng);
  const cased = applyCase(alarmDamage(crit.damage, state.alarmLevel), attackCase);
  const mitigated = applyPlayerMitigation(state, cased);
  return {
    state: mitigated.state,
    damage: mitigated.damage,
    absorbed: mitigated.absorbed,
    attackCase,
    isCrit: crit.isCrit,
  };
}

/** Carry one resolved enemy hit into the turn.
 *
 * Both enemy paths — the skill and the auto-attack — did this identically:
 * spend the shield, take the damage off the player's HP, log what the shield
 * absorbed, and push the number the player sees (ADR-0321). Only the attack
 * LINE differs, so the caller writes that.
 *
 * The rng is consumed in the same order as the inline copies (case → crit →
 * shield), so the seeded stream and every recorded curve are unchanged.
 */
function applyEnemyHit(
  working: GameState,
  enemy: Ice,
  rawDamage: number,
  playerHp: number,
  rng: () => number,
  logMessages: string[],
  vfx: CombatVfxInstance[],
): { readonly state: GameState; readonly playerHp: number; readonly hit: ResolvedHit } {
  const hit = resolveIncomingHit(working, enemy, rawDamage, rng);
  if (hit.absorbed > 0) {
    logMessages.push(`>>> shield absorbed ${hit.absorbed}`);
  }
  vfx.push(
    import_vfx_deterministic(
      "player_hit",
      "",
      durationForKind("player_hit"),
      undefined,
      undefined,
      // ADR-0321: the number the player sees is what reached their HP.
      hit.damage,
    ),
  );
  return { state: hit.state, playerHp: Math.max(0, playerHp - hit.damage), hit };
}

/** Boss phase → outgoing damage multiplier (ADR-0280 F.4). Phase 1 is the
 *  baseline and 4+ is the enraged ceiling; the chain was a five-deep ternary. */
function bossDamageMultiplierForPhase(phase: number): number {
  if (phase <= 0) return 1.0;
  if (phase === 2) return 1.25;
  if (phase === 3) return 1.5;
  if (phase >= 4) return 2.0;
  return 1.0;
}

/** Let one ICE take its action as a SKILL, if it has one to use.
 *
 * Returns `usedSkill: false` without touching the rng when the ICE has no
 * skills at all — the same short-circuit the inline version had, which is why
 * the seeded stream does not move. Otherwise it rolls once
 * (`enemyShouldUseSkill`), picks by archetype, and either lands a damaging skill
 * through `applyEnemyHit` or fires a non-damaging effect (ADR-0219 Option A).
 *
 * `newCooldowns` is mutated in place; the log and VFX arrays are appended to.
 * Extracted from `processEnemyTurns` (refactor 2026-11-24).
 */
function runEnemySkill(
  state: GameState,
  working: GameState,
  iceIndex: number,
  enemy: Ice,
  playerHp: number,
  newCooldowns: Record<string, number>,
  logMessages: string[],
  vfx: CombatVfxInstance[],
): { readonly state: GameState; readonly playerHp: number; readonly usedSkill: boolean } {
  let enemySkills = enemy.skills ?? [];

  if (isMutatorActive(state as unknown as MutableRunState, "stealth_only")) {
    const stealthEffects = ["dot", "poison", "debuff", "silence", "slow"];
    enemySkills = enemySkills.filter((s) => stealthEffects.includes(s.effect));
  }

  if (enemySkills.length === 0) return { state: working, playerHp, usedSkill: false };
  if (!enemyShouldUseSkill(enemy, Math.random, state.alarmLevel)) {
    return { state: working, playerHp, usedSkill: false };
  }

  const selectedSkill = selectSkillByPersonality(enemy, enemySkills);
  if (!selectedSkill) return { state: working, playerHp, usedSkill: false };

  const cooldownKey = `${enemy.id}_${selectedSkill.id}`;
  const remaining = newCooldowns[cooldownKey] ?? 0;
  if (remaining > 0) return { state: working, playerHp, usedSkill: false };

  if (selectedSkill.damage > 0) {
    const rawSkillDmg = selectedSkill.damage + enemy.tier * 2 + iceAttackBonus(working, iceIndex);
    const baseSkillDmg = Math.max(1, Number.isFinite(rawSkillDmg) ? rawSkillDmg : 1);
    // ADR-0161 `aggressive` archetype: +5% crit chance on the ICE's outgoing
    // damage. The roll is a pure function of the injected RNG and consumes the
    // same `Math.random` the balance harness controls, so the simulation stays
    // deterministic. ADR-0321: the case, then the crit, then the shield.
    const hit = applyEnemyHit(working, enemy, baseSkillDmg, playerHp, Math.random, logMessages, vfx);
    logMessages.push(
      `>>> ${enemy.name} uses ${selectedSkill.name}: ${hit.hit.damage} dmg${caseNote(hit.hit.attackCase)}${hit.hit.isCrit ? " CRITICAL" : ""}`,
    );
    newCooldowns[cooldownKey] = selectedSkill.cooldownMs;
    return { state: hit.state, playerHp: hit.playerHp, usedSkill: true };
  }

  // ADR-0219 Option A: a non-damaging skill fires as an effect instead of being
  // blocked by the `damage > 0` gate. It still consumes the ICE's action.
  const outcome = applyIceNonDamageEffect(working, iceIndex, enemy, selectedSkill);
  // `working` takes the outcome's state even when there is no message to log —
  // the effect may have moved `statusEffects` without saying anything.
  if (outcome.message === null) return { state: outcome.state, playerHp, usedSkill: false };
  logMessages.push(outcome.message);
  vfx.push(...outcome.vfx);
  newCooldowns[cooldownKey] = selectedSkill.cooldownMs;
  return { state: outcome.state, playerHp, usedSkill: true };
}

/** The runner's HP hit 0 during the enemy phase.
 *
 * Two outcomes, in order:
 *   - a `revive_once` piece refuses the flatline (ADR-0332) — the run continues
 *     from `working`, with the HP floor at `REVIVE_HP_PCT` of max
 *   - otherwise the run ends: a deceased jockey is recorded, the death summary
 *     is generated, and the phase becomes `dead`/`defeat` with the defeat VFX
 *
 * Extracted from `processEnemyTurns` (refactor 2026-11-24). It is the one branch
 * there that ends the run, and it reads nothing the enemy loop computed except
 * the values passed in.
 */
function resolvePlayerDeath(
  state: GameState,
  working: GameState,
  newCooldowns: Record<string, number>,
  rosterForReturn: ReadonlyArray<Ice>,
  newBossPhase: BossPhase,
  enemyTurnVfx: ReadonlyArray<CombatVfxInstance>,
): GameState {
  // ADR-0332: a piece can refuse the flatline once per run (MASTER_BODY).
  if (loadoutHasEffect(state, "revive_once") && state.reviveUsed !== true) {
    const hp = Math.max(1, Math.floor((state.player.maxHp * REVIVE_HP_PCT) / 100));
    return {
      ...working,
      skillCooldowns: newCooldowns,
      iceRoster: rosterForReturn,
      reviveUsed: true,
      player: { ...working.player, hp },
      message: "The body refuses to quit — one revive spent.",
    };
  }
  const jockey = createDeceasedJockey({
    name: state.mission.title,
    characterId: "novice",
    grade: state.mission.grade ?? 1,
    missionId: state.mission.id,
    inventory: state.inventory.programs.map((p) => p.id),
    missionsCompleted: 0,
    dataRecovered: 0,
    playtimeMinutes: Math.floor(state.turnCount * 0.5),
  });
  const summary = generateDeathSummary(
    jockey,
    state.totalRuns,
    state.totalDeaths + 1,
    Math.max(state.longestRunMinutes, Math.floor(state.turnCount * 0.5)),
  );
  return {
    ...state,
    runPhase: "dead",
    phase: "defeat",
    message: "FLATLINE",
    player: { ...state.player, hp: 0 },
    lastDeathSummary: summary,
    totalDeaths: state.totalDeaths + 1,
    deceasedJockeys: [...state.deceasedJockeys, jockey],
    skillCooldowns: newCooldowns,
    iceRoster: rosterForReturn,
    statusEffects: working.statusEffects,
    bossPhase: newBossPhase,
    vfxInstances: [
      ...state.vfxInstances,
      ...enemyTurnVfx,
      import_vfx_deterministic("defeat", "", durationForKind("defeat")),
    ],
    // ADR-0280: `lastEnemyAttackMs` / `counterWindowOpenMs` were wall-clock
    // stamps written here and read nowhere (the gate that read the first one
    // is gone). Left untouched rather than re-stamped with a clock the
    // reducer no longer reads.
    lastEnemyAttackMs: state.lastEnemyAttackMs,
    counterWindowOpenMs: state.counterWindowOpenMs,
  };
}

/** One enemy phase. The caller decides *when* — the turn, not a clock.
 *
 * ADR-0280. This used to open with a wall-clock gate:
 *
 *     const currentMs = Date.now();
 *     if (currentMs - state.lastEnemyAttackMs < AUTO_ATTACK_INTERVAL_MS) return state;
 *
 * which made difficulty depend on how long the player took per card, left the
 * reducer impure in a way the balance harness had to monkey-patch `Date.now`
 * to work around, and made a mission's real shape (4.4 encounters on average)
 * unmeasurable: the harness's per-encounter curve implied a grade-4 mission
 * survives 4% of the time, while a real browser session finished 53 of 53.
 *
 * `AUTO_ATTACK_INTERVAL_MS` survives as the **nominal unit** for authored
 * durations (`skillCooldowns` are written in ms; one enemy phase is worth
 * `AUTO_ATTACK_INTERVAL_MS` of them), so no authored number changes meaning.
 */

function processEnemyTurns(state: GameState): GameState {
  state = advanceDeadTarget(state);

  let playerHp = state.player.hp;
  const logMessages: string[] = [];
  const newCooldowns: Record<string, number> = { ...state.skillCooldowns };
  const enemyTurnVfx: CombatVfxInstance[] = [];

  for (const key of Object.keys(newCooldowns)) {
    newCooldowns[key] = Math.max(0, (newCooldowns[key] ?? 0) - AUTO_ATTACK_INTERVAL_MS);
  }

  let newBossPhase = state.bossPhase;
  if (state.bossPhase > 0) {
    const bossIce = state.iceRoster.find((ice) => ice.hp > 0);
    if (bossIce) {
      const tracker = {
        bossProfile: DEFAULT_BOSS_PROFILE,
        currentPhase: state.bossPhase,
        phaseChangeMs: 0,
        phaseChangeColor: "#ffffff",
      };
      const updated = checkPhaseTransition(
        tracker,
        bossIce.hp,
        bossIce.maxHp ?? 100,
        // ADR-0280: the phase is HP-threshold based; `tickMs` only stamps
        // `phaseChangeMs`, which nothing reads. Passing 0 keeps the reducer
        // clock-free.
        0,
      );
      if (updated.currentPhase > state.bossPhase && updated.currentPhase <= 4) {
        newBossPhase = updated.currentPhase as BossPhase;
        logMessages.push(
          `★ BOSS PHASE ${newBossPhase} — ${DEFAULT_BOSS_PROFILE.phases[newBossPhase - 1]?.label}`,
        );
      }
    }
  }

  const bossDamageMultiplier = bossDamageMultiplierForPhase(state.bossPhase);

  let rosterForReturn = state.iceRoster;
  if (state.bossPhase >= 4 && state.iceRoster.length < 3) {
    const minion: Ice = {
      // ADR-0280: a content-stable id. `Date.now()` here made two identical
      // reducer calls produce different ids, which the reducer-determinism
      // invariant forbids (and it read a clock inside the reducer).
      id: `minion_${state.turnCount}_${state.iceRoster.length}`,
      name: "Drone",
      tier: 1,
      hp: 30,
      maxHp: 30,
      armor: 0,
      personality: "aggressive",
      aggression: "standard",
    };
    rosterForReturn = [...state.iceRoster, minion];
    logMessages.push(`★ PHASE 4: Drone deployed!`);
  }

  // Working copy so the ICE-side effects (shield / regen / buff) can mutate
  // `statusEffects` and the roster's HP inside the loop. ADR-0219 Option A.
  // It starts from the roster that existed *before* the phase-4 minion was
  // appended: a freshly deployed minion acts from the next enemy turn on.
  let working: GameState = { ...state, iceRoster: state.iceRoster };

  for (let iceIndex = 0; iceIndex < working.iceRoster.length; iceIndex++) {
    const enemy = working.iceRoster[iceIndex];
    if (!enemy || enemy.hp <= 0) continue;

    const skill = runEnemySkill(
      state,
      working,
      iceIndex,
      enemy,
      playerHp,
      newCooldowns,
      logMessages,
      enemyTurnVfx,
    );
    working = skill.state;
    playerHp = skill.playerHp;

    if (!skill.usedSkill) {
      const rawAutoDmg = enemy.tier * 3 + (enemy.armor ?? 0);
      let autoDmg = Math.max(1, Number.isFinite(rawAutoDmg) ? rawAutoDmg : 1);
      // ADR-0211 fun-fix: per-grade ICE dmg modifier. Pairs with the HP cap in
      // ice_scaling.ts — cap contests g3+ (where tier-3+ natural HP > cap),
      // the bonus contests g1-g2 (where tier-1/2 natural HP < cap and the
      // opener otherwise kills the ICE before taking any meaningful dmg).
      // The value may be negative (g6 -20%): the g6 band is tanky enough that
      // the developed deck flatlined at the HP cap, so the climax needs an ICE
      // dmg *penalty* to stay attainable. Any non-zero value applies.
      // Skipped for boss rooms (bossPhase > 0): boss encounter tension is
      // already carried by phase multipliers (1.25x / 1.5x / 2x) so stacking
      // the per-grade modifier would tip the boss AI tests out of phase intent.
      if (state.bossPhase === 0) {
        const dmgBonusPct = iceDmgBonusPctForGrade(
          state.mission.grade ?? missionGradeOf(state.mission),
        );
        if (dmgBonusPct !== 0) {
          autoDmg = Math.max(1, Math.floor(autoDmg * (1 + dmgBonusPct / 100)));
        }
      }

      if (enemy.tier >= 3 && state.bossPhase > 0) {
        autoDmg = Math.floor(autoDmg * bossDamageMultiplier);
      }

      // ADR-0219 Option A: the `buff` bonus is added after the grade and
      // boss multipliers, so a temporary in-combat buff is worth the same
      // flat amount at every grade instead of being amplified by the
      // difficulty curve.
      autoDmg += iceAttackBonus(working, iceIndex);

      // ADR-0161 `aggressive` archetype: +5% crit chance on the ICE's
      // outgoing auto-attack. The roll is a pure function of the injected RNG
      // and consumes the same `Math.random` the balance harness controls, so
      // the simulation stays deterministic.
      // ADR-0321: the case, then the crit, then the shield pool (ADR-0255).
      const hit = applyEnemyHit(
        working,
        enemy,
        autoDmg,
        playerHp,
        Math.random,
        logMessages,
        enemyTurnVfx,
      );
      working = hit.state;
      playerHp = hit.playerHp;
      const autoCase = hit.hit.attackCase;

      if (enemy.tier >= 3 && state.bossPhase >= 3) {
        logMessages.push(
          `>>> ${enemy.name} AoE: ${hit.hit.damage} dmg (hits all!) ${caseNote(autoCase)}${hit.hit.isCrit ? " CRITICAL" : ""}`,
        );
      } else {
        logMessages.push(
          `>>> ${enemy.name} attacks: ${hit.hit.damage} dmg${caseNote(autoCase)}${hit.hit.isCrit ? " CRITICAL" : ""}`,
        );
      }
    }
  }

  // ADR-0219 Option A: advance the enemy-timed ICE effects (shield pool
  // lifetime, regen ticks, buff lifetime). One tick = one enemy turn.
  const iceEffectsBeforeTick = working.statusEffects;
  working = tickIceEffects(working);
  // ADR-0251 slice B: the tick used to drop ended ICE-cast effects silently.
  // Log lines only — `logMessages` is untouched.
  const endedIceEffectLines = statusEventLines(
    endedStatuses(iceEffectsBeforeTick, working.statusEffects),
    "off",
    working.iceRoster.length,
  );
  // The acted roster shares the prefix of `rosterForReturn`; the phase-4
  // minion is appended after it, so merge positionally (roster ids are not
  // unique — the encounter band repeats ids when a node has fewer ids than
  // the roster needs).
  rosterForReturn = [...working.iceRoster, ...rosterForReturn.slice(working.iceRoster.length)];

  if (playerHp <= 0) {
    return resolvePlayerDeath(
      state,
      working,
      newCooldowns,
      rosterForReturn,
      newBossPhase,
      enemyTurnVfx,
    );
  }

  const bossPhaseChangedInEnemyTurn = newBossPhase > state.bossPhase;

  const bossPhaseVfx: CombatVfxInstance[] =
    bossPhaseChangedInEnemyTurn && newBossPhase >= 1 && newBossPhase <= 4
      ? [
          import_vfx_ms(
            "boss_phase_transition",
            "",
            durationMsForKind("boss_phase_transition"),
            undefined,
            undefined,
            newBossPhase,
          ),
        ]
      : [];

  // ADR-0332: a piece can knit the body back each enemy phase (NANO_HIVE).
  if (playerHp > 0 && loadoutHasEffect(state, "nano_regen")) {
    playerHp = Math.min(state.player.maxHp, playerHp + NANO_REGEN_HP);
  }

  return {
    ...state,
    skillCooldowns: newCooldowns,
    iceRoster: rosterForReturn,
    statusEffects: working.statusEffects,
    bossPhase: newBossPhase,
    player: { ...state.player, hp: playerHp },
    lastEnemyAttackMs: state.lastEnemyAttackMs,
    counterWindowOpenMs: state.counterWindowOpenMs,
    message: logMessages.length > 0 ? logMessages[logMessages.length - 1] : state.message,
    combatLog:
      logMessages.length > 0 || endedIceEffectLines.length > 0
        ? [...logMessages.slice().reverse(), ...endedIceEffectLines, ...state.combatLog].slice(
            0,
            COMBAT_LOG_CAP,
          )
        : state.combatLog,
    vfxInstances:
      bossPhaseVfx.length > 0 || enemyTurnVfx.length > 0
        ? [...state.vfxInstances, ...enemyTurnVfx, ...bossPhaseVfx]
        : state.vfxInstances,
  };
}
